const storage = (() => {
  try { localStorage.setItem("__t", "1"); localStorage.removeItem("__t"); return localStorage }
  catch { const m = {}; return { getItem: (k) => (k in m ? m[k] : null), setItem: (k, v) => { m[k] = String(v) } } }
})()
let todos = JSON.parse(storage.getItem("todos") ?? "[]")
const list = document.querySelector("#list")
const left = document.querySelector("#left")
const form = document.querySelector("#new")

function render() {
  list.innerHTML = ""
  todos.forEach((todo, i) => {
    const li = document.createElement("li")
    li.textContent = todo.text
    li.classList.toggle("done", todo.done)
    li.addEventListener("click", () => {
      todos = todos.map((t, j) => (j === i ? { ...t, done: !t.done } : t))
      update()
    })
    list.append(li)
  })
  left.textContent = `${todos.filter((t) => !t.done).length} left`
}
function update() {
  storage.setItem("todos", JSON.stringify(todos))
  render()
}
form.addEventListener("submit", (e) => {
  e.preventDefault()
  const text = form.elements.text.value.trim()
  if (text) todos = [...todos, { text, done: false }]
  form.reset()
  update()
})
document.querySelector("#clear").addEventListener("click", () => {
  todos = todos.filter((t) => !t.done)
  update()
})
render()
